"""New application-parent geometry only; retained child evidence is not rerun."""
from pathlib import Path
import json

r = Path(__file__).resolve().parents[2]
out = r / 'artifacts/replica/windows-download'
cases = [dict(id=f'{lang}-{w}', language=lang, width=w, height=h)
         for lang in ['ko', 'en'] for w, h in [(960,720),(1180,720),(1280,900),(1600,900)]]
(r/'docs/replica/source/root-app-preflight-cases.json').write_text(json.dumps(cases,indent=2)+'\n')
html = '''<!doctype html><meta charset="utf-8"><title>Root preflight parent · original isolation</title>
<button id="record">Record preflight parent</button><div id="frames"></div><script>
const cases=CASES;const frames=cases.map(c=>{const f=document.createElement('iframe');f.width=c.width;f.height=c.height;f.style.border='0';f.style.display='none';f.srcdoc='<!doctype html><meta charset="utf-8"><link rel="stylesheet" href="root-appflow-original.css"><div id="app"></div><div id="dialog-host"></div><div id="toast-host"></div><div id="announcer" class="sr" aria-live="polite"></div><input id="file-open" hidden type="file"><script src="root-appflow-original.js"><\\/script>';document.getElementById('frames').append(f);return f});
document.getElementById('record').onclick=async()=>{const rows=[];try{for(let i=0;i<frames.length;i++){const f=frames[i],c=cases[i];f.style.display='block';if(f.contentDocument.readyState!=='complete')await new Promise(r=>f.addEventListener('load',r,{once:true}));f.contentWindow.eval('lang='+JSON.stringify(c.language)+';state=initial();state.connected=true;go("capabilities")');await f.contentDocument.fonts.ready;await new Promise(r=>requestAnimationFrame(()=>requestAnimationFrame(r)));await Promise.all(f.contentDocument.getAnimations().filter(a=>Number.isFinite(a.effect.getComputedTiming().endTime)).map(a=>a.finished.catch(()=>{})));const d=f.contentDocument,box=e=>{const b=e.getBoundingClientRect();return{x:b.x,y:b.y,width:b.width,height:b.height}};rows.push({id:c.id,viewport:{width:f.contentWindow.innerWidth,height:f.contentWindow.innerHeight},dpr:f.contentWindow.devicePixelRatio,topbar:box(d.querySelector('.topbar')),sidebar:box(d.querySelector('.rail')),content:box(d.getElementById('main')),page:box(d.querySelector('.page')),heading:box(d.querySelector('.page-heading')),footer:box(d.querySelector('.footer')),title:d.getElementById('screen-title').textContent,focus:d.activeElement.id,announcement:d.getElementById('announcer').textContent,scroll:d.getElementById('main').scrollTop,footerActions:[...d.querySelectorAll('.footer button[data-action]')].map(b=>({action:b.dataset.action,label:b.textContent.trim(),enabled:!b.disabled}))});f.style.display='none'}const os=new URLSearchParams(location.search).get('os')==='windows'?'windows':'mac';const res=await fetch('/evidence/root-appflow-preflight-'+os+'-source.json',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({scope:'New full application Preflight parent, programmatic navigation only',recording:new URLSearchParams(location.search).get('recording'),rows})});if(!res.ok)throw Error('Save '+res.status);document.getElementById('record').textContent='Recorded '+rows.length+' parents'}catch(e){document.getElementById('record').textContent='FAILED '+e.message;throw e}};
if(new URLSearchParams(location.search).get('record')==='1')window.addEventListener('load',()=>document.getElementById('record').click(),{once:true});
</script>'''.replace('CASES', json.dumps(cases))
(out/'root-app-preflight.html').write_text(html)
print(out/'root-app-preflight.html')
